//
// Compiles the embedded bitcode generated by the hip tapir target into fat
// binaries.
//
//===----------------------------------------------------------------------===//

#include "CGFBImpl.h"
#include "kitsune/Core/EmbUtils.h"
#include "kitsune/Core/SingletonUtils.h"
#include "kitsune/Core/TapirTargetOptions.h"
#include "kitsune/Core/TargetUtils.h"
#include "kitsune/Support/ToString.h"
#include "llvm/ADT/SmallString.h"
#include "llvm/ADT/StringExtras.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/LegacyPassManager.h"
#include "llvm/IR/Module.h"
#include "llvm/Support/FileSystem.h"
#include "llvm/Support/MemoryBuffer.h"
#include "llvm/Support/Path.h"
#include "llvm/Support/Program.h"
#include "llvm/Support/ToolOutputFile.h"
#include "llvm/Target/TargetMachine.h"

using namespace llvm;

namespace {

/// Helper class to generate code for AMD GPU's from embedded bitcode.
class CGFBHip {
private:
  const TapirTargetOptions &tto;
  const detail::CGFBOptions &cgfbOpts;

private:
  void embedObjFile(ToolOutputFile &objFile, Module &hostM) {
    ErrorOr<std::unique_ptr<MemoryBuffer>> bufOrErr =
        MemoryBuffer::getFile(objFile.getFilename());
    if (std::error_code ec = bufOrErr.getError()) {
      report_fatal_error(StringRef(llvm::join_items(
          " ", "could not load device code object file:", ec.message())));
    }

    const MemoryBuffer &buf = **bufOrErr;
    LLVMContext &ctx = hostM.getContext();
    size_t size = buf.getBufferSize();
    StringRef data = buf.getBuffer();

    Type *i8 = Type::getInt8Ty(ctx);
    Type *i64 = Type::getInt64Ty(ctx);
    Type *bufTy = ArrayType::get(i8, size);
    StructType *type = StructType::get(i64, bufTy);
    GlobalValue::LinkageTypes linkage = GlobalValue::PrivateLinkage;

    Constant *csz = ConstantInt::get(i64, size);
    Constant *cbuf = ConstantDataArray::getString(ctx, data, /*AddNull=*/false);
    Constant *init = ConstantStruct::get(type, {csz, cbuf});

    GlobalVariable *payload =
        new GlobalVariable(hostM, type, /*isConstant=*/true, linkage, init);
    payload->setAlignment(MaybeAlign(8));
    payload->addAttribute(Attribute::getWithTTID(ctx, TTID::Hip));
    payload->setSection(hipDeviceCodeSection);
    payload->setUnnamedAddr(GlobalValue::UnnamedAddr::Global);
  }

  std::unique_ptr<ToolOutputFile> createObject(Module &km) {
    LLVM_DEBUG(dbgs() << "\t- generating amdgpu object file...\n");

    SmallString<1024> objFilename;
    std::string model = join_items("-", "kithip", "%%%%%%%%", km.getName());
    sys::fs::createUniquePath(model.c_str(), objFilename, true);
    sys::path::replace_extension(objFilename, ".amdgpu.o");
    LLVM_DEBUG(dbgs() << "\t- amdgpu object file: '" << objFilename << "'.\n");

    std::error_code ec;
    auto objFile = std::make_unique<ToolOutputFile>(
        objFilename, ec, sys::fs::OpenFlags::OF_None);
    if (ec)
      report_fatal_error(Twine("Could not create amdgpu object file: ") +
                         ec.message());

    // The build system should have ensured that the AMDGPU target is
    // available.
    TargetMachine *tm =
        createTargetMachine(TTID::Hip, tto, cgfbOpts.cgOptLevel);
    assert(tm && "Could not create AMDGPU target machine");
    if (cgfbOpts.debugTargetMachine)
      detail::debugTargetMachine(*tm, errs());
    if (cgfbOpts.debugTargetOptions)
      dump(tm->Options, errs());
    if (cgfbOpts.debugMCTargetOptions)
      dump(tm->Options.MCOptions, errs());

    // Setup the passes and request that the output goes to the specified object
    // file.
    legacy::PassManager passMgr;
    if (tm->addPassesToEmitFile(passMgr, objFile->os(),
                                /*DwoOut=*/nullptr, CodeGenFileType::ObjectFile,
                                /*DisableVerify=*/false))
      report_fatal_error("AMDGPU object file generation failed");
    passMgr.run(km);

    LLVM_DEBUG(dbgs() << "AMDGPU object file generation complete.\n\n");
    return objFile;
  }

public:
  CGFBHip(const TapirTargetOptions &tto, const detail::CGFBOptions &cgfbOpts)
      : tto(tto), cgfbOpts(cgfbOpts) {}

  bool run(Module &hostM, Module &devM) {
    std::unique_ptr<ToolOutputFile> objFile = createObject(devM);
    embedObjFile(*objFile, hostM);

    if (cgfbOpts.keepFiles)
      objFile->keep();

    return false;
  }
};

} // namespace

// FIXME: We don't need the fatbin global here.
bool llvm::detail::cgfbHip(Module &hostM, Module &devM,
                           const TapirTargetOptions &tto,
                           const detail::CGFBOptions &cgfbOpts) {
  return CGFBHip(tto, cgfbOpts).run(hostM, devM);
}
